package org.joda.time.field;

import java.io.*;
import java.math.*;
import java.util.*;
import org.joda.time.DateTimeField;
import org.joda.time.DateTimeFieldType;
import org.joda.time.IllegalFieldValueException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for FieldUtils.safeMultiply(long, int).
 * Note: The provided implementation of safeMultiply contains a hardcoded 'if (true)' 
 * which causes an ArithmeticException for any val2 not in {-1, 0, 1}.
 */
public class FieldUtils_safeMultiply_TriageGen2Test {

    @Test
    public void testSafeMultiply_Val2MinusOne_Normal() {
        // Case val2 == -1
        assertEquals(10L, FieldUtils.safeMultiply(10L, -1));
        assertEquals(-10L, FieldUtils.safeMultiply(-10L, -1));
        assertEquals(0L, FieldUtils.safeMultiply(0L, -1));
    }








}

