public class FieldUtils_safeMultiply_TriageGen2Test {



    @Test
    public void testSafeMultiply_Val2MinusOne_Overflow() {
        // Case val2 == -1 and val1 == Long.MIN_VALUE
        try {
            FieldUtils.safeMultiply(Long.MIN_VALUE, -1);
            fail("Expected ArithmeticException due to overflow");
        } catch (ArithmeticException e) {
            assertTrue(e.getMessage().contains("Multiplication overflows a long"));
