package org.joda.time.field;

import java.io.*;
import java.math.*;
import java.util.*;
import org.joda.time.DateTimeField;
import org.joda.time.DateTimeFieldType;
import org.joda.time.IllegalFieldValueException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for FieldUtils.safeMultiply(long, int).
 * Note: The provided implementation of safeMultiply contains a hardcoded 'if (true)' 
 * which causes an ArithmeticException for any val2 not in {-1, 0, 1}.
 */
public class FieldUtils_safeMultiply_TriageGen2Test {









    @Test
    public void testSafeMultiply_OtherVal2_ThrowsException() {
        // Case val2 is not -1, 0, or 1. 
        // Due to the 'if (true)' block in the provided source code, this will always throw.
        try {
            FieldUtils.safeMultiply(10L, 2);
            fail("Expected ArithmeticException due to hardcoded if(true)");
        } catch (ArithmeticException e) {
            assertTrue(e.getMessage().contains("Multiplication overflows a long"));
        }

        try {
            FieldUtils.safeMultiply(10L, -2);
            fail("Expected ArithmeticException due to hardcoded if(true)");
        } catch (ArithmeticException e) {
            assertTrue(e.getMessage().contains("Multiplication overflows a long"));
        }
    }
}
